const MONEY=`package br.com.curso.aula141.dominio.valor;import java.math.*;import java.util.*;public final class Dinheiro{private final BigDecimal valor;private Dinheiro(BigDecimal valor){if(valor==null)throw new IllegalArgumentException("Valor obrigatorio.");this.valor=valor.setScale(2,RoundingMode.HALF_UP);}public static Dinheiro de(String valor){if(valor==null||valor.isBlank())throw new IllegalArgumentException("Valor em texto obrigatorio.");return new Dinheiro(new BigDecimal(valor));}public static Dinheiro zero(){return new Dinheiro(BigDecimal.ZERO);}public boolean positivo(){return valor.signum()>0;}public Dinheiro somar(Dinheiro outro){if(outro==null)throw new IllegalArgumentException("Outro valor obrigatorio.");return new Dinheiro(valor.add(outro.valor));}@Override public boolean equals(Object outro){return this==outro||outro instanceof Dinheiro d&&Objects.equals(valor,d.valor);}@Override public int hashCode(){return Objects.hash(valor);}@Override public String toString(){return "R$ "+valor;}}`;
const CLIENT=`package br.com.curso.aula141.dominio.cliente;public class Cliente{private final int id;private final String nome,telefone;private final boolean ativo;public Cliente(int id,String nome,String telefone){this(id,nome,telefone,true);}public Cliente(int id,String nome,String telefone,boolean ativo){if(id<=0||nome==null||nome.isBlank()||telefone==null||telefone.isBlank())throw new IllegalArgumentException("Cliente invalido.");this.id=id;this.nome=nome;this.telefone=telefone;this.ativo=ativo;}public boolean ativo(){return ativo;}public String telefone(){return telefone;}public String resumo(){return "Cliente "+id+" - "+nome+" | Telefone: "+telefone+" | Ativo: "+ativo;}}`;
const OS_CODE=`package br.com.curso.aula141.dominio.ordemservico;import java.util.*;public final class CodigoOs{private static final String PREFIXO="OS-";private final String valor;public CodigoOs(String valor){if(valor==null||valor.isBlank()||!valor.startsWith(PREFIXO))throw new IllegalArgumentException("Codigo da OS deve iniciar com OS-.");this.valor=valor;}public static CodigoOs deNumero(int ano,int numero){if(ano<=0||numero<=0)throw new IllegalArgumentException("Ano e numero devem ser positivos.");return new CodigoOs(PREFIXO+ano+"-"+String.format("%04d",numero));}@Override public boolean equals(Object outro){return this==outro||outro instanceof CodigoOs c&&Objects.equals(valor,c.valor);}@Override public int hashCode(){return Objects.hash(valor);}@Override public String toString(){return valor;}}`;
