const PERIOD=`package br.com.curso.aula141.dominio.ordemservico;import java.time.*;import java.util.*;public final class PeriodoAtendimento{private final LocalDate data;private final TurnoAtendimento turno;public PeriodoAtendimento(LocalDate data,TurnoAtendimento turno){if(data==null||turno==null)throw new IllegalArgumentException("Periodo invalido.");this.data=data;this.turno=turno;}public boolean mesmaData(PeriodoAtendimento outro){return outro!=null&&Objects.equals(data,outro.data);}@Override public boolean equals(Object outro){return this==outro||outro instanceof PeriodoAtendimento p&&Objects.equals(data,p.data)&&turno==p.turno;}@Override public int hashCode(){return Objects.hash(data,turno);}@Override public String toString(){return data+" - "+turno;}}`;
const ACTIVITY=`package br.com.curso.aula141.dominio.ordemservico;public final class AtividadeOs{private final String codigo,descricao;private StatusAtividade status=StatusAtividade.PENDENTE;AtividadeOs(String codigo,String descricao){if(codigo==null||codigo.isBlank()||descricao==null||descricao.isBlank())throw new IllegalArgumentException("Atividade invalida.");this.codigo=codigo;this.descricao=descricao;}boolean mesmoCodigo(String codigo){return codigo!=null&&this.codigo.equals(codigo);}boolean concluida(){return status==StatusAtividade.CONCLUIDA;}void concluir(){if(status==StatusAtividade.CANCELADA)throw new IllegalStateException("Atividade cancelada nao pode ser concluida.");if(status==StatusAtividade.CONCLUIDA)throw new IllegalStateException("Atividade ja concluida.");status=StatusAtividade.CONCLUIDA;}void cancelar(){if(status==StatusAtividade.CONCLUIDA)throw new IllegalStateException("Atividade concluida nao pode ser cancelada.");if(status==StatusAtividade.CANCELADA)throw new IllegalStateException("Atividade ja cancelada.");status=StatusAtividade.CANCELADA;}public String resumo(){return codigo+" - "+descricao+" | "+status;}}`;
const OCCURRENCE=`package br.com.curso.aula141.dominio.ordemservico;import java.time.*;public final class OcorrenciaOs{private final LocalDateTime dataHora=LocalDateTime.now();private final String descricao;OcorrenciaOs(String descricao){if(descricao==null||descricao.isBlank())throw new IllegalArgumentException("Ocorrencia invalida.");this.descricao=descricao;}public String resumo(){return dataHora+" | "+descricao;}}`;
const OS=`package br.com.curso.aula141.dominio.ordemservico;import br.com.curso.aula141.dominio.cliente.Cliente;import java.util.*;public class OrdemServico{private final CodigoOs codigo;private final Cliente cliente;private final String origem;private final PrioridadeOs prioridade;private PeriodoAtendimento periodo;private StatusOs status=StatusOs.AGENDADA;private int reagendamentos;private String motivoCancelamento="";private final List<AtividadeOs> atividades=new ArrayList<>();private final List<OcorrenciaOs> ocorrencias=new ArrayList<>();OrdemServico(CodigoOs codigo,Cliente cliente,PeriodoAtendimento periodo,PrioridadeOs prioridade,String origem){if(codigo==null||cliente==null||periodo==null||prioridade==null||origem==null||origem.isBlank())throw new IllegalArgumentException("Dados da OS obrigatorios.");if(!cliente.ativo())throw new IllegalStateException("OS nao pode ser criada para cliente inativo.");this.codigo=codigo;this.cliente=cliente;this.periodo=periodo;this.prioridade=prioridade;this.origem=origem;registrar("OS criada. Origem: "+origem+" | Periodo: "+periodo);}public CodigoOs codigo(){return codigo;}public Cliente cliente(){return cliente;}public StatusOs status(){return status;}public PrioridadeOs prioridade(){return prioridade;}public boolean encerrada(){return status==StatusOs.CONCLUIDA||status==StatusOs.CANCELADA;}private void exigirAberta(String mensagem){if(encerrada())throw new IllegalStateException(mensagem);}public void adicionarAtividade(String codigo,String descricao){exigirAberta("OS encerrada nao pode receber atividade.");if(existeAtividade(codigo))throw new IllegalArgumentException("Atividade ja existe: "+codigo);atividades.add(new AtividadeOs(codigo,descricao));registrar("Atividade adicionada: "+codigo);}public void concluirAtividade(String codigo){exigirAberta("OS encerrada nao pode alterar atividade.");buscar(codigo).concluir();registrar("Atividade concluida: "+codigo);}public void cancelarAtividade(String codigo){exigirAberta("OS encerrada nao pode alterar atividade.");buscar(codigo).cancelar();registrar("Atividade cancelada: "+codigo);}public void reagendar(PeriodoAtendimento novo){exigirAberta("OS encerrada nao pode ser reagendada.");if(novo==null||periodo.equals(novo))throw new IllegalArgumentException("Novo periodo deve ser diferente.");PeriodoAtendimento anterior=periodo;periodo=novo;status=StatusOs.REAGENDADA;reagendamentos++;registrar("OS reagendada de "+anterior+" para "+novo);}public void concluir(){if(status==StatusOs.CANCELADA)throw new IllegalStateException("OS cancelada nao pode ser concluida.");if(atividades.isEmpty())throw new IllegalStateException("OS sem atividades nao pode ser concluida.");if(!todasAtividadesConcluidas())throw new IllegalStateException("Todas as atividades precisam estar concluidas.");status=StatusOs.CONCLUIDA;registrar("OS concluida");}public void cancelar(String motivo){if(motivo==null||motivo.isBlank())throw new IllegalArgumentException("Motivo obrigatorio.");if(status==StatusOs.CONCLUIDA)throw new IllegalStateException("OS concluida nao pode ser cancelada.");if(status==StatusOs.CANCELADA)throw new IllegalStateException("OS ja cancelada.");status=StatusOs.CANCELADA;motivoCancelamento=motivo;registrar("OS cancelada: "+motivo);}public boolean existeAtividade(String codigo){return atividades.stream().anyMatch(a->a.mesmoCodigo(codigo));}private AtividadeOs buscar(String codigo){return atividades.stream().filter(a->a.mesmoCodigo(codigo)).findFirst().orElseThrow(()->new IllegalArgumentException("Atividade nao encontrada: "+codigo));}public boolean todasAtividadesConcluidas(){return !atividades.isEmpty()&&atividades.stream().allMatch(AtividadeOs::concluida);}public int quantidadeAtividades(){return atividades.size();}public List<AtividadeOs> atividades(){return List.copyOf(atividades);}public List<OcorrenciaOs> ocorrencias(){return List.copyOf(ocorrencias);}private void registrar(String texto){ocorrencias.add(new OcorrenciaOs(texto));}public String resumo(){return "OS "+codigo+" | "+cliente.resumo()+" | "+periodo+" | prioridade="+prioridade+" | origem="+origem+" | "+status+" | reagendamentos="+reagendamentos+" | motivo="+motivoCancelamento+" | atividades="+atividades.size()+" | ocorrencias="+ocorrencias.size();}}`;
const BUILDER=`package br.com.curso.aula141.dominio.ordemservico;import br.com.curso.aula141.dominio.cliente.Cliente;public class OrdemServicoBuilder{private CodigoOs codigo;private Cliente cliente;private PeriodoAtendimento periodo;private PrioridadeOs prioridade=PrioridadeOs.NORMAL;private String origem="SISTEMA";public OrdemServicoBuilder codigo(CodigoOs codigo){this.codigo=codigo;return this;}public OrdemServicoBuilder cliente(Cliente cliente){this.cliente=cliente;return this;}public OrdemServicoBuilder periodo(PeriodoAtendimento periodo){this.periodo=periodo;return this;}public OrdemServicoBuilder prioridade(PrioridadeOs prioridade){this.prioridade=prioridade;return this;}public OrdemServicoBuilder origem(String origem){this.origem=origem;return this;}public OrdemServico build(){return new OrdemServico(codigo,cliente,periodo,prioridade,origem);}}`;
const REPO=`package br.com.curso.aula141.infra;import br.com.curso.aula141.dominio.ordemservico.*;import java.util.*;public class OrdemServicoRepositorioMemoria{private final List<OrdemServico> ordens=new ArrayList<>();public void salvar(OrdemServico os){if(os==null)throw new IllegalArgumentException("OS obrigatoria.");for(int i=0;i<ordens.size();i++)if(ordens.get(i).codigo().equals(os.codigo())){ordens.set(i,os);System.out.println("[INFRA] OS atualizada: "+os.codigo());return;}ordens.add(os);System.out.println("[INFRA] OS inserida: "+os.codigo());}public boolean existe(CodigoOs codigo){return ordens.stream().anyMatch(os->os.codigo().equals(codigo));}public int quantidade(){return ordens.size();}}`;
