const CREATE_UC=`package br.com.curso.aula141.aplicacao;import br.com.curso.aula141.dominio.ordemservico.OrdemServico;import br.com.curso.aula141.infra.*;public class CriarOrdemServicoUseCase{private final OrdemServicoRepositorioMemoria repositorio;private final NotificadorOsConsole notificador;public CriarOrdemServicoUseCase(OrdemServicoRepositorioMemoria r,NotificadorOsConsole n){if(r==null||n==null)throw new IllegalArgumentException("Dependencias obrigatorias.");repositorio=r;notificador=n;}public void executar(OrdemServico os){if(os==null)throw new IllegalArgumentException("OS obrigatoria.");if(repositorio.existe(os.codigo()))throw new IllegalStateException("OS ja cadastrada: "+os.codigo());repositorio.salvar(os);notificador.enviarCriacao(os);}}`;
const RESCHEDULE_UC=`package br.com.curso.aula141.aplicacao;import br.com.curso.aula141.dominio.ordemservico.*;import br.com.curso.aula141.infra.*;public class ReagendarOrdemServicoUseCase{private final OrdemServicoRepositorioMemoria repositorio;private final NotificadorOsConsole notificador;public ReagendarOrdemServicoUseCase(OrdemServicoRepositorioMemoria r,NotificadorOsConsole n){repositorio=r;notificador=n;}public void executar(OrdemServico os,PeriodoAtendimento novo){if(os==null)throw new IllegalArgumentException("OS obrigatoria.");os.reagendar(novo);repositorio.salvar(os);notificador.enviarReagendamento(os);}}`;
