const MAIN_APP=`package br.com.curso.aula141.app;import br.com.curso.aula141.aplicacao.*;import br.com.curso.aula141.dominio.cliente.Cliente;import br.com.curso.aula141.dominio.ordemservico.*;import br.com.curso.aula141.infra.*;import java.time.*;public class RevisaoOoDominioApp{public static void main(String[]a){Cliente cliente=new Cliente(10,"Ana Silva","(11) 99999-0000");OrdemServico os=new OrdemServicoBuilder().codigo(CodigoOs.deNumero(2026,1)).cliente(cliente).periodo(new PeriodoAtendimento(LocalDate.of(2026,7,20),TurnoAtendimento.MANHA)).prioridade(PrioridadeOs.ALTA).origem("PORTAL_CLIENTE").build();os.adicionarAtividade("ATV-001","Instalar produto");os.adicionarAtividade("ATV-002","Validar funcionamento");OrdemServicoRepositorioMemoria r=new OrdemServicoRepositorioMemoria();NotificadorOsConsole n=new NotificadorOsConsole();new CriarOrdemServicoUseCase(r,n).executar(os);new ReagendarOrdemServicoUseCase(r,n).executar(os,new PeriodoAtendimento(LocalDate.of(2026,7,22),TurnoAtendimento.TARDE));os.concluirAtividade("ATV-001");os.concluirAtividade("ATV-002");new ConcluirOrdemServicoUseCase(r,n).executar(os);System.out.println(os.resumo());System.out.println("Ordens distintas salvas: "+r.quantidade());}}`;
