const CONTRACT=`package br.com.curso.aula141.dominio.contrato;import br.com.curso.aula141.dominio.cliente.Cliente;import br.com.curso.aula141.dominio.valor.Dinheiro;import java.util.*;public class Contrato{private final String codigo;private final Cliente cliente;private final String origem;private final List<ServicoContrato> servicos=new ArrayList<>();private final List<EventoContrato> eventos=new ArrayList<>();private StatusContrato status=StatusContrato.RASCUNHO;private String motivoCancelamento="";Contrato(String codigo,Cliente cliente,String origem){if(codigo==null||!codigo.startsWith("CONT-")||cliente==null||origem==null||origem.isBlank())throw new IllegalArgumentException("Contrato invalido.");if(!cliente.ativo())throw new IllegalStateException("Cliente inativo.");this.codigo=codigo;this.cliente=cliente;this.origem=origem;registrar("Contrato criado: "+origem);}public String codigo(){return codigo;}public StatusContrato status(){return status;}private void exigirRascunho(){if(status!=StatusContrato.RASCUNHO)throw new IllegalStateException("Contrato nao esta em rascunho.");}public void adicionarServico(String codigo,String nome,Dinheiro valor){exigirRascunho();if(servicos.stream().anyMatch(s->s.mesmoCodigo(codigo)))throw new IllegalArgumentException("Servico duplicado.");servicos.add(new ServicoContrato(codigo,nome,valor));registrar("Servico adicionado: "+codigo);}public Dinheiro valorMensal(){Dinheiro total=Dinheiro.zero();for(ServicoContrato s:servicos)total=total.somar(s.valor());return total;}public void ativar(){exigirRascunho();if(servicos.isEmpty())throw new IllegalStateException("Contrato sem servicos.");status=StatusContrato.ATIVO;registrar("Contrato ativado");}public void cancelar(String motivo){if(status!=StatusContrato.ATIVO)throw new IllegalStateException("Somente contrato ATIVO pode ser cancelado.");if(motivo==null||motivo.isBlank())throw new IllegalArgumentException("Motivo obrigatorio.");status=StatusContrato.CANCELADO;motivoCancelamento=motivo;registrar("Contrato cancelado: "+motivo);}public List<ServicoContrato> servicos(){return List.copyOf(servicos);}public List<EventoContrato> eventos(){return List.copyOf(eventos);}private void registrar(String texto){eventos.add(new EventoContrato(texto));}public String resumo(){return "Contrato "+codigo+" | "+cliente.resumo()+" | origem="+origem+" | servicos="+servicos.size()+" | mensal="+valorMensal()+" | "+status+" | motivo="+motivoCancelamento+" | eventos="+eventos.size();}}`;
