const CONTRACT_APP=`package br.com.curso.aula141.appcontrato;import br.com.curso.aula141.aplicacao.contrato.*;import br.com.curso.aula141.dominio.cliente.Cliente;import br.com.curso.aula141.dominio.contrato.*;import br.com.curso.aula141.dominio.valor.Dinheiro;import br.com.curso.aula141.infra.contrato.*;public class RevisaoContratoApp{public static void main(String[]a){Contrato c=new ContratoBuilder().codigo("CONT-001").cliente(new Cliente(30,"Empresa A","1133334444")).origem("PORTAL").build();c.adicionarServico("SERV-1","Instalacao",Dinheiro.de("150"));c.adicionarServico("SERV-2","Manutencao",Dinheiro.de("80"));ContratoRepositorioMemoria r=new ContratoRepositorioMemoria();NotificadorContratoConsole n=new NotificadorContratoConsole();new AtivarContratoUseCase(r,n).executar(c);new CancelarContratoUseCase(r,n).executar(c,"Encerramento solicitado");System.out.println(c.resumo());System.out.println("Contratos distintos salvos: "+r.quantidade());}}`;
const CONTRACT_BLOCK=`package br.com.curso.aula141.appcontrato;import br.com.curso.aula141.dominio.cliente.Cliente;import br.com.curso.aula141.dominio.contrato.*;public class RevisaoContratoBloqueioApp{public static void main(String[]a){Contrato c=new ContratoBuilder().codigo("CONT-002").cliente(new Cliente(31,"Empresa B","1155556666")).build();try{c.ativar();}catch(IllegalStateException e){System.out.println("Ativacao bloqueada: "+e.getMessage());}System.out.println(c.resumo());}}`;
const TESTS=`package br.com.curso.aula141.app;import br.com.curso.aula141.dominio.cliente.Cliente;import br.com.curso.aula141.dominio.contrato.*;import br.com.curso.aula141.dominio.ordemservico.*;import br.com.curso.aula141.dominio.valor.Dinheiro;import java.time.*;public class TesteRevisao141{private static int passou;private static void ok(boolean c){if(!c)throw new AssertionError();passou++;}private static void falha(Class<? extends Throwable> tipo,Runnable acao){try{acao.run();throw new AssertionError();}catch(Throwable e){if(!tipo.isInstance(e))throw e;passou++;}}private static OrdemServico nova(){return new OrdemServicoBuilder().codigo(CodigoOs.deNumero(2026,9)).cliente(new Cliente(1,"Ana","11999990000")).periodo(new PeriodoAtendimento(LocalDate.of(2026,7,20),TurnoAtendimento.MANHA)).build();}public static void main(String[]a){ok(Dinheiro.de("10").equals(Dinheiro.de("10.00")));ok(Dinheiro.de("10").somar(Dinheiro.de("2.50")).equals(Dinheiro.de("12.50")));ok(CodigoOs.deNumero(2026,1).toString().equals("OS-2026-0001"));ok(new PeriodoAtendimento(LocalDate.of(2026,7,20),TurnoAtendimento.MANHA).equals(new PeriodoAtendimento(LocalDate.of(2026,7,20),TurnoAtendimento.MANHA)));OrdemServico os=nova();ok(os.prioridade()==PrioridadeOs.NORMAL);falha(IllegalStateException.class,()->new OrdemServicoBuilder().codigo(CodigoOs.deNumero(2026,2)).cliente(new Cliente(2,"B","1",false)).periodo(new PeriodoAtendimento(LocalDate.of(2026,7,20),TurnoAtendimento.MANHA)).build());ok(os.status()==StatusOs.AGENDADA);os.adicionarAtividade("A1","Instalar");ok(os.quantidadeAtividades()==1);falha(UnsupportedOperationException.class,()->os.atividades().clear());falha(IllegalStateException.class,os::concluir);os.concluirAtividade("A1");ok(os.todasAtividadesConcluidas());os.concluir();ok(os.status()==StatusOs.CONCLUIDA);falha(IllegalStateException.class,()->os.adicionarAtividade("A2","Validar"));Contrato c=new ContratoBuilder().codigo("CONT-9").cliente(new Cliente(3,"C","2")).build();falha(IllegalStateException.class,c::ativar);c.adicionarServico("S1","Servico",Dinheiro.de("50"));ok(c.valorMensal().equals(Dinheiro.de("50")));c.ativar();ok(c.status()==StatusContrato.ATIVO);System.out.println(passou+" testes passaram");}}`;
const EVIDENCE=`# EVIDENCIAS_AULA_141\n\n- [ ] Expliquei os treze conceitos usando classes concretas do projeto.\n- [ ] Compilei as 31 fontes com javac -encoding UTF-8.\n- [ ] Executei o fluxo completo e o bloqueio da OS.\n- [ ] Provoquei as cinco violações da arena de invariantes.\n- [ ] Depurei Builder, raiz, filho, ocorrência, use case e infraestrutura.\n- [ ] Transferi os critérios para Contrato e executei os dois cenários.\n- [ ] A suíte encerrou com 16 testes passaram.\n- [ ] Fiz um commit sem out/ nem .class.`;

