function CodeTabs({files}){const[index,setIndex]=useState(0);return <div className="guided-code-tabs"><div className="guided-code-tab-list">{files.map(([name],i)=><button type="button" className={i===index?"active":""} onClick={()=>setIndex(i)} key={name}>{name}</button>)}</div><Code name={files[index][0]}>{files[index][1]}</Code></div>}
function Console({children}){return <section className="guided-console"><header><Play size={16}/>Console esperado</header><pre>{children}</pre></section>}

const CONCEPTS=[["Objeto de valor","Dinheiro, CodigoOs e PeriodoAtendimento valem pelos dados."],["Entidade","Cliente, OS e Contrato preservam identidade e ciclo de vida."],["Encapsulamento","Nenhum setter permite pular transições."],["Tell, Don't Ask","O app ordena concluirAtividade; não muda o filho."],["Invariante","OS só conclui com todas as atividades concluídas."],["Enum","Status, turno e prioridade têm vocabulário fechado."],["Composição","Atividade e ocorrência nascem dentro da OS."],["Coleção protegida","List.copyOf expõe leitura sem mutação estrutural."],["Agregado","OrdemServico é a única porta de mudança dos filhos."],["Builder","Monta cinco dados com nomes e padrões explícitos."],["Aplicação","Use cases coordenam intenção, domínio e efeitos."],["Infraestrutura","Repositório e notificador ficam fora do núcleo."],["Baixo acoplamento","O domínio não importa infra nem tecnologia."]];
function ConceptRadar(){const[index,setIndex]=useState(0);return <div className="b141-radar"><nav>{CONCEPTS.map((x,i)=><button type="button" className={i===index?"active":""} onClick={()=>setIndex(i)} key={x[0]}><span>{String(i+1).padStart(2,"0")}</span>{x[0]}</button>)}</nav><main><span>EVIDÊNCIA {index+1} DE {CONCEPTS.length}</span><h3>{CONCEPTS[index][0]}</h3><p>{CONCEPTS[index][1]}</p><div><CheckCircle2/><b>Você domina quando consegue apontar a linha de código que prova isso.</b></div></main></div>}
