function OwnershipLab(){const[selected,setSelected]=useState("atividade");const data={cliente:["ASSOCIAÇÃO","Cliente existe antes e depois da OS","construtor public · identidade própria"],atividade:["COMPOSIÇÃO","Atividade pertence ao ciclo de vida da OS","construtor e mudança package-private"],ocorrencia:["COMPOSIÇÃO","Ocorrência nasce como consequência de um comando","o app não fabrica histórico"]}[selected];return <div className="b141-ownership"><nav>{["cliente","atividade","ocorrencia"].map(x=><button type="button" className={selected===x?"active":""} onClick={()=>setSelected(x)} key={x}>{x}</button>)}</nav><main><div className="root"><Boxes/><span>RAIZ</span><b>OrdemServico</b></div><ArrowRight/><div className={data[0]==="ASSOCIAÇÃO"?"associate":"child"}><span>{data[0]}</span><h3>{selected==="cliente"?"Cliente":selected==="atividade"?"AtividadeOs":"OcorrenciaOs"}</h3><p>{data[1]}</p><small>{data[2]}</small></div></main></div>}
