function BuilderLab(){const[fields,setFields]=useState({codigo:false,cliente:false,periodo:false,prioridade:false,origem:false});const toggle=k=>setFields(f=>({...f,[k]:!f[k]}));const required=fields.codigo&&fields.cliente&&fields.periodo;return <div className="b141-builder"><aside><span>ORDEMSERVICOBUILDER</span>{Object.entries(fields).map(([k,v])=><button type="button" className={v?"set":""} onClick={()=>toggle(k)} key={k}><span>{v?<Check size={14}/>:"·"}</span>.{k}(...)</button>)}<button type="button" className="build" disabled={!required}>.build()</button></aside><main><div><span>PADRÕES</span><b>prioridade = NORMAL</b><b>origem = SISTEMA</b></div><ArrowRight/><div className={required?"valid":"invalid"}><ShieldCheck/><span>CONSTRUTOR DA ENTIDADE</span><b>{required?"dados obrigatórios presentes":"ainda faltam dados"}</b><small>Builder organiza; OrdemServico valida.</small></div></main><footer>{required?"O objeto final pode nascer válido. Campos opcionais usam padrões explícitos.":"Marque código, cliente e período. build() não deve criar uma OS incompleta."}</footer></div>}
