const ERRORS=[["Regra no app","main verifica atividades antes de concluir.","Outra entrada pode ignorar a regra.","Mantenha a invariante em OrdemServico.concluir()."],["Use case rouba regra","caso de uso altera status ou percorre filhos.","O domínio fica anêmico.","Use case chama um comando expressivo da raiz."],["Filho público demais","app cria ou conclui AtividadeOs diretamente.","A raiz deixa de garantir consistência.","Use package-private e exponha comandos na OS."],["Lista mutável","atividades() devolve a ArrayList interna.","Código externo apaga ou injeta filhos.","Retorne List.copyOf."],["Status como String","aceita CONCLUIDAAA em runtime.","Estados inválidos circulam pelo sistema.","Use enum e transições na entidade."],["Domínio salva","OS conhece Repository ou SQL.","Tecnologia contamina regra e teste.","Persistência fica em infraestrutura."],["Domínio notifica","concluir() envia mensagem.","Falha externa parece falha do negócio.","Notificador roda depois da regra."],["Builder fura invariantes","build entrega objeto sem cliente/período.","Surge uma OS parcialmente válida.","Construtor final valida todos os obrigatórios."]];
