function ContractLab(){const[state,setState]=useState("RASCUNHO"),[services,setServices]=useState(0),[events,setEvents]=useState(["Contrato criado"]);const add=()=>{if(state!=="RASCUNHO")return setEvents(e=>[...e,"BLOQUEIO: contrato não está em rascunho"]);setServices(s=>s+1);setEvents(e=>[...e,"Serviço adicionado"])};const activate=()=>{if(state!=="RASCUNHO"||services===0)return setEvents(e=>[...e,"BLOQUEIO: ativação recusada"]);setState("ATIVO");setEvents(e=>[...e,"Contrato ativado","INFRA: salvo e avisado"])};const cancel=()=>{if(state!=="ATIVO")return setEvents(e=>[...e,"BLOQUEIO: somente ATIVO cancela"]);setState("CANCELADO");setEvents(e=>[...e,"Contrato cancelado","INFRA: salvo e avisado"])};return <div className="b141-contract"><aside><span>TRANSFERÊNCIA DE MODELO</span><strong>CONT-001</strong><b className={state.toLowerCase()}>{state}</b><small>{services} serviço(s)</small><button type="button" onClick={add}>Adicionar serviço</button><button type="button" onClick={activate}>Ativar</button><button type="button" onClick={cancel}>Cancelar</button><button type="button" className="reset" onClick={()=>{setState("RASCUNHO");setServices(0);setEvents(["Contrato criado"])}}><RotateCcw size={14}/>Reiniciar</button></aside><main><div><ShieldCheck/><b>Contrato</b><small>raiz: serviços + eventos</small></div><ArrowRight/><div><GitBranch/><b>Use cases</b><small>ativar e cancelar</small></div><ArrowRight/><div><Database/><b>Infra</b><small>atualiza e notifica</small></div><pre>{events.join("\n")}</pre></main></div>}

